-- v1.2 更新公告（2026-10-21）
-- 与后台「系统设置 → 更新公告」PUT /auth/settings/changelog 写入格式完全一致
-- （site_settings.key = app_changelog，value 为 {version,title,updated_at,items} JSON）
-- 覆盖范围：v1.1（2026-10-13）之后上线的全部用户可见变化
INSERT INTO site_settings (key, value) VALUES ('app_changelog', '{"version":"v1.2","title":"v1.2 更新公告：飞书提醒上线，首页新增「今日早报」","updated_at":"2026-10-21","items":["飞书提醒正式上线：到期、面试、审批提醒可推送到本人飞书（单聊）。管理员在「系统设置 → 飞书集成」配置企业自建应用，成员点右上角飞书图标、扫码绑定本人账号即可使用","绑定更安全：授权后会先确认「这是你本人的飞书账号吗」再完成绑定，防止绑错账号；一个飞书只能绑定一个系统账号，换绑需先解绑","群机器人推送：不想配应用？在飞书群添加自定义机器人、把 webhook 地址填进「飞书集成」，2 分钟即可用；发送模式支持「仅个人」「仅群」「群 + 个人」三种","首页新增「今日早报」：今天到期的待办、合同、试用期，今天的面试与待审批事项一屏总览，不用逐个页面翻","背调中心瘦身：详情只保留授权、结论、报告三件事，结论随行显示在 Offer 弹窗，支持删除记录","智能匹配不再「藏」着：工具栏直达；入职 → 合同 → 社保办理链路已打通","AI 支持使用自己的 Key：官方配额用尽后，可填写自己的 DeepSeek Key 继续使用","新增操作审计日志：谁在何时修改了什么，全程可追溯（管理员可见）","移动端新增「面试」页：随时查看今天有几场面试、谁来、几点开始","体验修复：修复发起审批偶发失败、二维码偶发不显示、早报同一条规则重复提示等 10 余处问题"]}')
ON CONFLICT(key) DO UPDATE SET value = excluded.value;
